35	  sessionId: string | null;
36	  workspaceId?: string;
37	  newSessionWorkspaceId?: string;
38	  onSessionCreated?: (sessionId: string) => void;
39	  onEditAction?: () => void;
40	  showWorkspaceHub?: boolean;
41	}
