43	export const SessionChatView = (props: SessionChatViewProps) => {
44	  const { t } = useTranslation(["projects", "tickets"]);
45	  const {
46	    sessionId,
47	    workspaceId,
48	    newSessionWorkspaceId,
49	    onSessionCreated,
50	    onEditAction,
51	    showWorkspaceHub = true,
52	  } = props;
53	  const { projectId } = useParams({ strict: false });
54	
55	  const sessionAgent = useSessionAgent(sessionId);
56	  const lastSelectedAgent = useProjectSettingsStore((s) => s.lastSelectedAgent);
57	  const lastSelectedModels = useProjectSettingsStore((s) => s.lastSelectedModels);
58	  const agent = sessionId && sessionAgent ? sessionAgent : lastSelectedAgent;
59	  const model = lastSelectedModels[0] ?? undefined;
60	
61	  const projectSettingsStore = useProjectSettingsStoreApi();
62	  const draftKey = sessionId ?? "__new__";
63	  const [chatDraft, setChatDraft] = useState(() => projectSettingsStore.getState().chatDraftsBySession[draftKey] ?? "");
64	  const setSessionDraft = useProjectSettingsStore((state) => state.setSessionDraft);
65	  const clearSessionDraft = useProjectSettingsStore((state) => state.clearSessionDraft);
66	  const { messages, isStreaming, approvalRequest, reconnect } = useSessionStream(sessionId);
67	  const sessionWorkspace = useSessionWorkspace(sessionId);
68	  const { data: workspaceDiffSummary } = useTicketAttemptDiffSummary(showWorkspaceHub ? sessionWorkspace?.id : null);
69	  const createSession = useCreateProjectSession();
70	  const followUp = useFollowUpSession();
71	  const stopSession = useStopSession();
72	  const [pendingFollowUp, setPendingFollowUp] = useState<PendingFollowUpState | null>(null);
73	  const pendingIdRef = useRef(0);
74	  const editCountRef = useRef(0);
75	  const isWorkspaceInitializing = sessionWorkspace?.initializing ?? false;
76	
77	  const sessionStatus = useSessionStatus(sessionId);
78	
79	  useResetEditCountOnSessionChange(sessionId, editCountRef);
80	  useReconnectWhenWorkspaceReady(isWorkspaceInitializing, reconnect);
81	  useReconnectOnExternalResume(sessionStatus, isStreaming, reconnect);
82	  useEditActionNotifier(messages, onEditAction, editCountRef);
83	  useSyncPendingFollowUp({
84	    messages,
85	    pendingFollowUp,
86	    sessionId,
87	    setPendingFollowUp,
88	  });
89	
90	  useEffect(() => {
91	    setChatDraft(projectSettingsStore.getState().chatDraftsBySession[draftKey] ?? "");
92	  }, [draftKey, projectSettingsStore]);
93	
94	  const displayedMessages = mergeMessagesWithPendingFollowUp(
95	    messages,
96	    shouldShowPendingFollowUp(pendingFollowUp, sessionId) ? pendingFollowUp : null,
97	  );
98	  const workspaceHub = buildSessionWorkspaceHubPanelModel({
99	    showWorkspaceHub,
100	    isWorkspaceInitializing,
101	    setupError: sessionWorkspace?.setupError ?? null,
102	    projectId,
103	    workspace: sessionWorkspace,
104	    diffSummary: workspaceDiffSummary,
105	    statusLabel: t("tickets:conversation.workspace.settingUp"),
106	    changesLabel: (count) => t("tickets:diff.filesChanged", { count }),
107	  });
108	  const loadingContent = sessionId ? <ChatSkeleton /> : undefined;
109	  const canInterrupt = canInterruptSession(sessionStatus, sessionId);
110	  const effectiveStreaming = isStreaming || isWorkspaceInitializing;
111	  const emptyStateTitle = sessionId ? t("chatInput.session.notFoundTitle") : t("sessions.nextBuildTitle");
112	  const emptyStateDescription = sessionId ? t("chatInput.session.notFoundDescription") : "";
113	  const effectiveWorkspaceId = resolveNewSessionWorkspaceId({
114	    sessionId,
115	    workspaceId,
116	    newSessionWorkspaceId,
117	  });
118	
119	  return (
120	    <ChatPanel
121	      messages={displayedMessages}
122	      streaming={effectiveStreaming}
123	      onInterruptMessage={canInterrupt ? () => stopSession.mutate(sessionId!) : undefined}
124	      workspaceInitializing={isWorkspaceInitializing}
125	      emptyStateTitle={emptyStateTitle}
126	      emptyStateDescription={emptyStateDescription}
127	      loadingContent={loadingContent}
128	      chatInputPlaceholder={t("sessions.followUpPlaceholder")}
129	      chatInputDefaultValue={chatDraft}
130	      onSubmitMessage={(text: string) =>
131	        submitSessionMessage({
132	          sessionId,
133	          projectId,
134	          agent,
135	          model,
136	          workspaceId: effectiveWorkspaceId,
137	          text,
138	          messages,
139	          pendingIdRef,
140	          clearSessionDraft,
141	          setChatDraft,
142	          setPendingFollowUp,
143	          createSession,
144	          followUp,
145	          reconnect,
146	          onSessionCreated,
147	        })
148	      }
149	      onChatInputChange={(text: string) => setSessionDraft(sessionId, text)}
150	      workspaceHub={workspaceHub ? <SessionChatWorkspaceHubPanel {...workspaceHub} /> : undefined}
151	      repoMenu={
152	        <Flex
153	          key={sessionId}
154	          justifyContent="space-between"
155	          align="center"
156	          gap="2xs"
157	          w="full"
158	          minW="0"
159	          px="xs"
160	          pb="xs"
161	          wrap="nowrap"
162	        >
163	          <Box flexShrink="0">
164	            <AgentBrowserContainer sessionId={sessionId} />
165	          </Box>
166	          <RepoBrowserContainer sessionId={sessionId} />
167	        </Flex>
168	      }
169	      approvalPrompt={<SessionChatApprovalPromptPanel sessionId={sessionId} approvalRequest={approvalRequest} />}
170	    />
