39	
40	    emitter.emit(PATCH_EVENT, patch);
41	  };
42	
43	  const getHistory = () => [...history];
44	
45	  const subscribe = (): AsyncIterable<JsonPatch> => ({
46	    [Symbol.asyncIterator]: () => {
47	      const queue: JsonPatch[] = [];
48	      let resolve: ((value: IteratorResult<JsonPatch>) => void) | null = null;
49	      let done = false;
50	
51	      const onPatch = (patch: JsonPatch) => {
52	        if (resolve) {
53	          const r = resolve;
54	          resolve = null;
55	          r({ value: patch, done: false });
56	        } else {
57	          queue.push(patch);
58	        }
59	      };
60	
61	      const onClose = () => {
62	        done = true;
63	        emitter.off(PATCH_EVENT, onPatch);
64	        emitter.off(CLOSE_EVENT, onClose);
65	
66	        if (resolve) {
67	          const r = resolve;
68	          resolve = null;
69	          r({ value: undefined as never, done: true });
70	        }
71	      };
72	
73	      emitter.on(PATCH_EVENT, onPatch);
74	      emitter.on(CLOSE_EVENT, onClose);
75	
76	      return {
77	        next: () => {
78	          if (queue.length > 0) {
79	            return Promise.resolve({ value: queue.shift()!, done: false });
80	          }
81	
82	          if (done) {
83	            return Promise.resolve({ value: undefined as never, done: true });
84	          }
85	
86	          return new Promise<IteratorResult<JsonPatch>>((r) => {
87	            resolve = r;
88	          });
89	        },
90	
