102	      let historyIndex = 0;
103	      const liveIterator = subscribe()[Symbol.asyncIterator]();
104	
105	      return {
106	        next: () => {
107	          if (historyIndex < historySnapshot) {
108	            return Promise.resolve({ value: history[historyIndex++], done: false });
109	          }
110	
111	          return liveIterator.next();
112	        },
113	
114	        return: () => liveIterator.return!(undefined as never),
115	      };
116	    },
117	  });
118	
